__device__ __forceinline__ void coop_grid_barrier(
        unsigned int* g_bar, int gridSize, unsigned int& local_sense) {
    __syncthreads();
    if (threadIdx.x == 0) {
        __threadfence();
        unsigned int old = atomicInc(&g_bar[0], (unsigned int)(gridSize - 1));
        if (old == (unsigned int)(gridSize - 1)) {
            // last arriver: counter auto-wrapped to 0 by atomicInc; flip sense.
            __threadfence();
