// Apply block reflector to the trailing submatrix. Every CTA grid-strides over
// COLUMN TILES of width CT; within a tile it does the WY update as two row-tiled
// GEMMs (V staged through smem in row strips of RB):
//   pass 1:  W  = V^T C          (W is nb x CT, accumulated across strips)
//            W' = T^T W
//   pass 2:  C -= V W'
// V = Acm[:, p:p+nb] (implicit unit diag, V[p+i,i]=1, zero above), rows >= p.
// CT trailing columns of C stay in global (read once in pass 1, read+written in
// pass 2). T (nb x nb upper-tri) and W/W' (nb x CT) live in smem.
template <int TPB, int NBMAX, int CT, int RB>
__device__ void coop_trailing_update(float* __restrict__ Acm, const float* __restrict__ Tg,
                                     float* dsmem, int n, int p, int nb) {
    const int tid = threadIdx.x;
    // partition dynamic smem
    float* Ts  = dsmem;                       // nb*nb   (col-major: Ts[l + i*nb])
    float* Ws  = Ts + (size_t)NBMAX * NBMAX;  // nb*CT   (col-major: Ws[i + g*nb])
    float* Wps = Ws + (size_t)NBMAX * CT;     // nb*CT   (col-major: Wps[i + g*nb])
    float* Vs  = Wps + (size_t)NBMAX * CT;    // RB*nb   (col-major: Vs[rr + i*RB])
    // cache T
    for (int idx = tid; idx < nb * nb; idx += TPB) Ts[idx] = Tg[idx % nb + (idx / nb) * NBMAX];
    __syncthreads();

    const int tstart = p + nb;
    for (int g0 = tstart + blockIdx.x * CT; g0 < n; g0 += gridDim.x * CT) {
        int ct = CT; if (g0 + ct > n) ct = n - g0;

        // ---- pass 1: W[i,g] = sum_{r>=p} V[r,i] C[r,g] ----
        for (int idx = tid; idx < nb * ct; idx += TPB) Ws[idx] = 0.f;
        __syncthreads();
        for (int r0 = p; r0 < n; r0 += RB) {
            int rb = RB; if (r0 + rb > n) rb = n - r0;
            // load V strip Vs[rr, i] = V[r0+rr, i]  (unit diag, zero above diag)
            for (int idx = tid; idx < rb * nb; idx += TPB) {
                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
                Vs[rr + i * RB] = vv;
            }
            __syncthreads();
            // each thread owns (i,g) pairs; accumulate over the strip's rows.
            for (int idx = tid; idx < nb * ct; idx += TPB) {
                int g = idx / nb, i = idx % nb;
                const float* Cg = Acm + (size_t)(g0 + g) * n;
                float acc = 0.f;
                for (int rr = 0; rr < rb; ++rr) acc += Vs[rr + i * RB] * Cg[r0 + rr];
                Ws[i + g * nb] += acc;
            }
            __syncthreads();
        }
        // ---- W' = T^T W :  W'[i,g] = sum_{l<=i} T[l,i] W[l,g]  (double-buffered) ----
        // negate W' so pass 2 does C += V*W'  (== C -= V W').
        for (int idx = tid; idx < nb * ct; idx += TPB) {
            int g = idx / nb, i = idx % nb;
            float acc = 0.f;
            for (int l = 0; l <= i; ++l) acc += Ts[l + i * nb] * Ws[l + g * nb];
            Wps[i + g * nb] = -acc;
        }
        __syncthreads();
        // ---- pass 2: C[r,g] += V[r,i] * W'[i,g] ----
        for (int r0 = p; r0 < n; r0 += RB) {
            int rb = RB; if (r0 + rb > n) rb = n - r0;
            for (int idx = tid; idx < rb * nb; idx += TPB) {
                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
                Vs[rr + i * RB] = vv;
            }
            __syncthreads();
            for (int idx = tid; idx < rb * ct; idx += TPB) {
                int g = idx / rb, rr = idx % rb, r = r0 + rr;
                float* Cg = Acm + (size_t)(g0 + g) * n;
                float acc = 0.f;
                int imax = r - p; if (imax >= nb) imax = nb - 1;
                for (int i = 0; i <= imax; ++i) acc += Vs[rr + i * RB] * Wps[i + g * nb];
                Cg[r] += acc;
            }
            __syncthreads();
        }
    }
}

template <int TPB, int NBMAX, int CT, int RB>
__global__ void qr_coop_kernel(const float* __restrict__ A, float* __restrict__ Acm,
                               float* __restrict__ H, float* __restrict__ tau,
                               float* __restrict__ Tg, unsigned int* __restrict__ g_bar,
                               int n, int gridSize) {
    extern __shared__ float dsmem[];
    const int tid = threadIdx.x;
    const int gtid = blockIdx.x * TPB + tid;
    const int gstride = gridDim.x * TPB;
    unsigned int sense = 0u;

    // row-major A -> column-major Acm (all CTAs)
    for (size_t idx = gtid; idx < (size_t)n * n; idx += gstride) {
        int r = idx / n, c = idx % n;
        Acm[(size_t)c * n + r] = A[(size_t)r * n + c];
    }
    coop_grid_barrier(g_bar, gridSize, sense);

    for (int p = 0; p < n; p += NBMAX) {
        int nb = NBMAX; if (p + nb > n) nb = n - p;
        if (blockIdx.x == 0) coop_panel_factor<TPB, NBMAX>(Acm, Tg, tau, dsmem, n, p, nb);
        coop_grid_barrier(g_bar, gridSize, sense);
        coop_trailing_update<TPB, NBMAX, CT, RB>(Acm, Tg, dsmem, n, p, nb);
        coop_grid_barrier(g_bar, gridSize, sense);
    }

    // column-major Acm -> row-major H (all CTAs)
    for (size_t idx = gtid; idx < (size_t)n * n; idx += gstride) {
        int r = idx / n, c = idx % n;
        H[(size_t)r * n + c] = Acm[(size_t)c * n + r];
    }
}

template <int NBMAX, int CT, int RB>
static size_t coop_smem_bytes(int n) {
    // dynamic smem must cover BOTH the panel sub-panel (rows[p,n) x NBMAX, max at
    // p=0 -> n*NBMAX) and the trailing-update buffers.
    size_t panel = (size_t)n * NBMAX;
    size_t trail = (size_t)NBMAX * NBMAX + 2 * (size_t)NBMAX * CT + (size_t)RB * NBMAX;
    size_t fcount = panel > trail ? panel : trail;
    return fcount * sizeof(float);
}

template <int TPB, int NBMAX, int CT, int RB>
static int coop_max_grid(size_t sh) {
    int blocks = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks, qr_coop_kernel<TPB, NBMAX, CT, RB>, TPB, sh);
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
    return blocks * sms;
}

template <int TPB, int NBMAX, int CT, int RB>
static void coop_dispatch(const float* A, float* Acm, float* H, float* tau, float* Tg,
                          unsigned int* g_bar, int n, int gridcap) {
    size_t sh = coop_smem_bytes<NBMAX, CT, RB>(n);
    cudaFuncSetAttribute(qr_coop_kernel<TPB, NBMAX, CT, RB>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize, (int)sh);
    int maxg = coop_max_grid<TPB, NBMAX, CT, RB>(sh);
    int grid = maxg; if (gridcap > 0 && gridcap < grid) grid = gridcap;
    if (grid < 1) grid = 1;
    qr_coop_kernel<TPB, NBMAX, CT, RB><<<grid, TPB, sh>>>(A, Acm, H, tau, Tg, g_bar, n, grid);
}

void qr_coop_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr, int64_t tau_ptr,
