// ===========================================================================
// BATCHED TWO-KERNEL blocked QR for large n (n>1024), small batch B.
//   The grid-barrier megakernel above is occupancy-limited to 12.5% because its
//   per-block smem = n*NB (panel sub-panel) forces 1 block/SM EVEN for the
//   trailing update (the dominant work). This version splits panel factor and
//   trailing update into SEPARATE kernel launches (the launch boundary is the
//   barrier -- NO cross-CTA atomics needed, capturable). The trailing kernel
//   uses a tiny smem footprint -> high occupancy + a large grid; the panel
//   kernel runs B blocks (one per matrix), so its big smem only costs B SMs.
//   All B matrices are factored CONCURRENTLY (panel kernel = B blocks; trailing
//   kernel grid-strides over (matrix, column-tile) work items).
// Acm: column-major B*n*n. Tg: B*NBMAX*NBMAX compact-WY T. tau: B*n.
// ===========================================================================

// transpose row-major A (B,n,n) -> column-major Acm (per matrix Acm[b][c*n+r]).
__global__ void qr_transpose_in(const float* __restrict__ A, float* __restrict__ Acm,
                                int B, int n) {
    const size_t total = (size_t)B * n * n;
    for (size_t idx = (size_t)blockIdx.x * blockDim.x + threadIdx.x; idx < total;
         idx += (size_t)gridDim.x * blockDim.x) {
        int b = idx / ((size_t)n * n);
        size_t rem = idx - (size_t)b * n * n;
        int r = rem / n, c = rem % n;
        Acm[(size_t)b * n * n + (size_t)c * n + r] = A[(size_t)b * n * n + (size_t)r * n + c];
    }
}
__global__ void qr_transpose_out(const float* __restrict__ Acm, float* __restrict__ H,
                                 int B, int n) {
    const size_t total = (size_t)B * n * n;
    for (size_t idx = (size_t)blockIdx.x * blockDim.x + threadIdx.x; idx < total;
         idx += (size_t)gridDim.x * blockDim.x) {
        int b = idx / ((size_t)n * n);
        size_t rem = idx - (size_t)b * n * n;
        int r = rem / n, c = rem % n;
        H[(size_t)b * n * n + (size_t)r * n + c] = Acm[(size_t)b * n * n + (size_t)c * n + r];
    }
}

// PANEL FACTOR kernel: grid = B (block b factors matrix b's panel [p,p+nb)).
// Active sub-panel rows[p,n) x nb loaded into dynamic smem (ldp*nb floats,
// sized by the host for this p), factored on-chip; reflectors+R written back to
// Acm[b]; compact-WY T built into Tg[b]. Identical math to coop_panel_factor.
template <int TPB, int NBMAX>
__global__ void qr_panel_kernel(float* __restrict__ Acm_all, float* __restrict__ Tg_all,
                                float* __restrict__ tau_all, int B, int n, int p, int nb) {
    extern __shared__ float Ps[];          // ldp * nb (col-major Ps[rr + j*ldp])
    const int b = blockIdx.x;
    if (b >= B) return;
    float* Acm = Acm_all + (size_t)b * n * n;
    float* Tg  = Tg_all + (size_t)b * NBMAX * NBMAX;
    float* taub = tau_all + (size_t)b * n;

    const int NWARP = TPB / 32;
    const int REDSZ = (NBMAX * NWARP > TPB) ? NBMAX * NWARP : TPB;
    __shared__ float red[REDSZ];
    __shared__ float sval[4];
    __shared__ float zsh[NBMAX];
    __shared__ float taus[NBMAX];
    const int tid = threadIdx.x;
    const int lane = tid & 31, warp = tid >> 5;
    const int ldp = n - p;

    for (int idx = tid; idx < ldp * nb; idx += TPB) {
        int j = idx / ldp, rr = idx % ldp;
        Ps[rr + j * ldp] = Acm[(size_t)(p + j) * n + (p + rr)];
    }
    __syncthreads();

    for (int j = 0; j < nb; ++j) {
        float* pj = Ps + (size_t)j * ldp;
        int rj = j;
        float partial = 0.f;
        for (int rr = rj + tid; rr < ldp; rr += TPB) { float x = pj[rr]; partial += x * x; }
        red[tid] = partial; __syncthreads();
        for (int s = TPB / 2; s > 0; s >>= 1) { if (tid < s) red[tid] += red[tid + s]; __syncthreads(); }
        if (tid == 0) {
            float xnorm = sqrtf(red[0]);
            float alpha = pj[rj];
            float beta = (alpha >= 0.f) ? -xnorm : xnorm;
            float tval, invden;
            if (xnorm > 0.f && (alpha - beta) != 0.f) {
                tval = (beta - alpha) / beta; invden = 1.f / (alpha - beta);
            } else { tval = 0.f; invden = 0.f; beta = alpha; }
            sval[0] = beta; sval[1] = tval; sval[2] = invden;
        }
        __syncthreads();
        float beta = sval[0], tval = sval[1], invden = sval[2];
        for (int rr = rj + 1 + tid; rr < ldp; rr += TPB) pj[rr] *= invden;
        __syncthreads();
        if (tid == 0) { pj[rj] = 1.f; taus[j] = tval; }
        __syncthreads();
        int ntrail = nb - (j + 1);
        if (ntrail > 0) {
            float pw[NBMAX];
            #pragma unroll
            for (int t = 0; t < NBMAX; ++t) pw[t] = 0.f;
            for (int rr = rj + tid; rr < ldp; rr += TPB) {
                float vr = pj[rr];
                for (int t = 0; t < ntrail; ++t)
                    pw[t] += vr * Ps[(size_t)(j + 1 + t) * ldp + rr];
            }
            for (int t = 0; t < ntrail; ++t) {
                float v = pw[t];
                #pragma unroll
                for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
                if (lane == 0) red[t * NWARP + warp] = v;
            }
            __syncthreads();
            if (tid < ntrail) {
                float w = 0.f;
                for (int wi = 0; wi < NWARP; ++wi) w += red[tid * NWARP + wi];
                zsh[tid] = tval * w;
            }
            __syncthreads();
            for (int t = 0; t < ntrail; ++t) {
                float tw = zsh[t];
                float* pjj = Ps + (size_t)(j + 1 + t) * ldp;
                for (int rr = rj + tid; rr < ldp; rr += TPB) pjj[rr] -= tw * pj[rr];
            }
            __syncthreads();
        }
        if (tid == 0) pj[rj] = beta;
        __syncthreads();
    }
    for (int i = tid; i < nb; i += TPB) { Tg[(size_t)i + (size_t)i * NBMAX] = taus[i]; taub[p + i] = taus[i]; }
    __syncthreads();
    for (int l = 1; l < nb; ++l) {
        const float* Vl = Ps + (size_t)l * ldp;
        float pz[NBMAX];
        #pragma unroll
        for (int t = 0; t < NBMAX; ++t) pz[t] = 0.f;
        for (int rr = l + tid; rr < ldp; rr += TPB) {
            float vl = (rr == l) ? 1.f : Vl[rr];
            for (int i = 0; i < l; ++i) {
                const float* Vi = Ps + (size_t)i * ldp;
                float vi = (rr == i) ? 1.f : Vi[rr];
                pz[i] += vi * vl;
            }
        }
        for (int i = 0; i < l; ++i) {
            float v = pz[i];
            #pragma unroll
            for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
            if (lane == 0) red[i * NWARP + warp] = v;
        }
        __syncthreads();
        if (tid < l) {
            float zz = 0.f;
            for (int wi = 0; wi < NWARP; ++wi) zz += red[tid * NWARP + wi];
            zsh[tid] = zz;
        }
        __syncthreads();
        float tl = taus[l];
        for (int i = tid; i < l; i += TPB) {
            float acc = 0.f;
            for (int m = i; m < l; ++m) acc += Tg[(size_t)i + (size_t)m * NBMAX] * zsh[m];
            Tg[(size_t)i + (size_t)l * NBMAX] = -tl * acc;
        }
        __syncthreads();
    }
    for (int idx = tid; idx < ldp * nb; idx += TPB) {
        int j = idx / ldp, rr = idx % ldp;
        Acm[(size_t)(p + j) * n + (p + rr)] = Ps[rr + j * ldp];
    }
}

// TRAILING kernel: grid-strides over (matrix b, column-tile g0) work items.
// Small smem (Ts + Ws + Wps + Vs) -> high occupancy, large grid. For each work
// item applies the block reflector to CT trailing columns of matrix b:
//   W = V^T C ; W' = T^T W ; C -= V W'  (V staged through smem in RB-row strips).
template <int TPB, int NBMAX, int CT, int RB>
__global__ void qr_trailing_kernel(float* __restrict__ Acm_all, const float* __restrict__ Tg_all,
                                   int B, int n, int p, int nb) {
    extern __shared__ float dsmem[];
    float* Ts  = dsmem;                       // nb*nb
    float* Ws  = Ts + (size_t)NBMAX * NBMAX;  // nb*CT
    float* Wps = Ws + (size_t)NBMAX * CT;     // nb*CT
    float* Vs  = Wps + (size_t)NBMAX * CT;    // RB*nb
    const int tid = threadIdx.x;

    const int tstart = p + nb;
    const int ntiles = (n - tstart + CT - 1) / CT;   // column tiles per matrix
    if (ntiles <= 0) return;
    const long totwork = (long)B * ntiles;

    for (long widx = blockIdx.x; widx < totwork; widx += gridDim.x) {
        int b = widx / ntiles;
        int tileIdx = widx - (long)b * ntiles;
        int g0 = tstart + tileIdx * CT;
        int ct = CT; if (g0 + ct > n) ct = n - g0;
        float* Acm = Acm_all + (size_t)b * n * n;
        const float* Tg = Tg_all + (size_t)b * NBMAX * NBMAX;

        // cache T for this matrix
        for (int idx = tid; idx < nb * nb; idx += TPB) Ts[idx] = Tg[idx % nb + (idx / nb) * NBMAX];
        __syncthreads();

        // pass 1: W = V^T C
        for (int idx = tid; idx < nb * ct; idx += TPB) Ws[idx] = 0.f;
        __syncthreads();
        for (int r0 = p; r0 < n; r0 += RB) {
            int rb = RB; if (r0 + rb > n) rb = n - r0;
            for (int idx = tid; idx < rb * nb; idx += TPB) {
                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
                Vs[rr + i * RB] = vv;
            }
            __syncthreads();
            for (int idx = tid; idx < nb * ct; idx += TPB) {
                int g = idx / nb, i = idx % nb;
                const float* Cg = Acm + (size_t)(g0 + g) * n;
                float acc = 0.f;
                for (int rr = 0; rr < rb; ++rr) acc += Vs[rr + i * RB] * Cg[r0 + rr];
                Ws[i + g * nb] += acc;
            }
            __syncthreads();
        }
        // W' = -T^T W
        for (int idx = tid; idx < nb * ct; idx += TPB) {
            int g = idx / nb, i = idx % nb;
            float acc = 0.f;
            for (int l = 0; l <= i; ++l) acc += Ts[l + i * nb] * Ws[l + g * nb];
            Wps[i + g * nb] = -acc;
        }
        __syncthreads();
        // pass 2: C += V W'
        for (int r0 = p; r0 < n; r0 += RB) {
            int rb = RB; if (r0 + rb > n) rb = n - r0;
            for (int idx = tid; idx < rb * nb; idx += TPB) {
                int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = p + i;
                float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
                Vs[rr + i * RB] = vv;
            }
            __syncthreads();
            for (int idx = tid; idx < rb * ct; idx += TPB) {
                int g = idx / rb, rr = idx % rb, r = r0 + rr;
                float* Cg = Acm + (size_t)(g0 + g) * n;
                float acc = 0.f;
                int imax = r - p; if (imax >= nb) imax = nb - 1;
                for (int i = 0; i <= imax; ++i) acc += Vs[rr + i * RB] * Wps[i + g * nb];
                Cg[r] += acc;
            }
            __syncthreads();
        }
    }
}

template <int TPB, int NBMAX, int CT, int RB>
static int trailing_max_grid(size_t sh) {
    int blocks = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks, qr_trailing_kernel<TPB, NBMAX, CT, RB>, TPB, sh);
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
    return blocks * sms;
}

template <int TPB, int NBMAX, int CT, int RB>
static void coop2_run(float* Acm, float* Tg, float* tau, int B, int n) {
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
    // trailing kernel: tiny smem -> high occupancy; cap grid to one wave.
    size_t trail_sh = ((size_t)NBMAX * NBMAX + 2 * (size_t)NBMAX * CT + (size_t)RB * NBMAX) * sizeof(float);
    int tgrid = trailing_max_grid<TPB, NBMAX, CT, RB>(trail_sh);
    if (tgrid < 1) tgrid = sms;
    // panel kernel: dynamic smem ldp*nb (sized per p); cap to device opt-in.
    cudaFuncSetAttribute(qr_panel_kernel<TPB, NBMAX>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize, (int)((size_t)n * NBMAX * sizeof(float)));
    for (int p = 0; p < n; p += NBMAX) {
        int nb = NBMAX; if (p + nb > n) nb = n - p;
        size_t panel_sh = (size_t)(n - p) * nb * sizeof(float);
        qr_panel_kernel<TPB, NBMAX><<<B, TPB, panel_sh>>>(Acm, Tg, tau, B, n, p, nb);
        if (p + nb < n)
            qr_trailing_kernel<TPB, NBMAX, CT, RB><<<tgrid, TPB, trail_sh>>>(Acm, Tg, B, n, p, nb);
    }
}

// driver: A(row-major) -> Acm(col-major) -> factor -> H(row-major).
template <int TPB, int NBMAX, int CT, int RB>
static void coop2_dispatch(const float* A, float* Acm, float* H, float* tau, float* Tg,
                           int B, int n) {
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
    int cgrid = sms * 4;
    qr_transpose_in<<<cgrid, TPB>>>(A, Acm, B, n);
    coop2_run<TPB, NBMAX, CT, RB>(Acm, Tg, tau, B, n);
    qr_transpose_out<<<cgrid, TPB>>>(Acm, H, B, n);
}

