void qr_coop2_launch(int64_t A_ptr, int64_t Acm_ptr, int64_t H_ptr, int64_t tau_ptr,
                     int64_t Tg_ptr, int B, int n, int NB) {
    const float* A = reinterpret_cast<const float*>(A_ptr);
    float* Acm = reinterpret_cast<float*>(Acm_ptr);
    float* H = reinterpret_cast<float*>(H_ptr);
    float* tau = reinterpret_cast<float*>(tau_ptr);
    float* Tg = reinterpret_cast<float*>(Tg_ptr);
    const int TPB = 256;
    const int CT = 32;
    const int RB = 64;
    switch (NB) {
        case 8:  coop2_dispatch<TPB, 8,  CT, RB>(A, Acm, H, tau, Tg, B, n); break;
        case 16: coop2_dispatch<TPB, 16, CT, RB>(A, Acm, H, tau, Tg, B, n); break;
        case 24: coop2_dispatch<TPB, 24, CT, RB>(A, Acm, H, tau, Tg, B, n); break;
        case 32: coop2_dispatch<TPB, 32, CT, RB>(A, Acm, H, tau, Tg, B, n); break;
        default: coop2_dispatch<TPB, 16, CT, RB>(A, Acm, H, tau, Tg, B, n); break;
    }
