// ===========================================================================
// TWO-LEVEL panel for the batched scheme: factor a WIDE panel of width NB using
// inner sub-blocks of width IB (each held in smem at (n-ps)*IB, which fits even
// when (n-p)*NB would not). This decouples the trailing block width NB (which we
// want LARGE -> the trailing update re-reads C n/NB times, so HBM traffic ~1/NB)
// from the smem limit. The panel kernel still runs B blocks, so its cost is on
// B SMs; the wide T is built from the global reflectors. The same trailing
// kernel then runs with the large NB.
// ===========================================================================

// Factor inner sub-block [ps,ps+ib) (cols local 0..ib-1) of matrix Acm, holding
// rows[ps,n) x ib in smem Ps; write reflectors+R back to Acm; fill the IB-block
// diagonal of the wide T (Tg col-major, NBMAX-leading) at columns [ps-p..].
template <int TPB, int IB, int NBMAX>
__device__ void wpanel_inner_factor(float* __restrict__ Acm, float* __restrict__ Tg,
                                    float* __restrict__ taub, float* Ps,
                                    float* red, float* sval, float* zsh, float* taus,
                                    int n, int p, int ps, int ib) {
    const int NWARP = TPB / 32;
    const int tid = threadIdx.x;
    const int lane = tid & 31, warp = tid >> 5;
    const int ldp = n - ps;
    for (int idx = tid; idx < ldp * ib; idx += TPB) {
        int j = idx / ldp, rr = idx % ldp;
        Ps[rr + j * ldp] = Acm[(size_t)(ps + j) * n + (ps + rr)];
    }
    __syncthreads();
    for (int j = 0; j < ib; ++j) {
        float* pj = Ps + (size_t)j * ldp;
        int rj = j;
        float partial = 0.f;
        for (int rr = rj + tid; rr < ldp; rr += TPB) { float x = pj[rr]; partial += x * x; }
        red[tid] = partial; __syncthreads();
        for (int s = TPB / 2; s > 0; s >>= 1) { if (tid < s) red[tid] += red[tid + s]; __syncthreads(); }
        if (tid == 0) {
            float xnorm = sqrtf(red[0]);
            float alpha = pj[rj];
            float beta = (alpha >= 0.f) ? -xnorm : xnorm;
            float tval, invden;
            if (xnorm > 0.f && (alpha - beta) != 0.f) { tval = (beta - alpha) / beta; invden = 1.f / (alpha - beta); }
            else { tval = 0.f; invden = 0.f; beta = alpha; }
            sval[0] = beta; sval[1] = tval; sval[2] = invden;
        }
        __syncthreads();
        float beta = sval[0], tval = sval[1], invden = sval[2];
        for (int rr = rj + 1 + tid; rr < ldp; rr += TPB) pj[rr] *= invden;
        __syncthreads();
        if (tid == 0) { pj[rj] = 1.f; taus[j] = tval; }
        __syncthreads();
        int ntrail = ib - (j + 1);
        if (ntrail > 0) {
            float pw[IB];
            #pragma unroll
            for (int t = 0; t < IB; ++t) pw[t] = 0.f;
            for (int rr = rj + tid; rr < ldp; rr += TPB) {
                float vr = pj[rr];
                for (int t = 0; t < ntrail; ++t) pw[t] += vr * Ps[(size_t)(j + 1 + t) * ldp + rr];
            }
            for (int t = 0; t < ntrail; ++t) {
                float v = pw[t];
                #pragma unroll
                for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
                if (lane == 0) red[t * NWARP + warp] = v;
            }
            __syncthreads();
            if (tid < ntrail) { float w = 0.f; for (int wi = 0; wi < NWARP; ++wi) w += red[tid * NWARP + wi]; zsh[tid] = tval * w; }
            __syncthreads();
            for (int t = 0; t < ntrail; ++t) {
                float tw = zsh[t];
                float* pjj = Ps + (size_t)(j + 1 + t) * ldp;
                for (int rr = rj + tid; rr < ldp; rr += TPB) pjj[rr] -= tw * pj[rr];
            }
            __syncthreads();
        }
        if (tid == 0) pj[rj] = beta;
        __syncthreads();
    }
    // diagonal IB-block of wide T (recurrence within the inner block, V from smem)
    int co = ps - p;     // wide-column offset of this inner block
    for (int i = tid; i < ib; i += TPB) { Tg[(size_t)(co + i) + (size_t)(co + i) * NBMAX] = taus[i]; taub[ps + i] = taus[i]; }
    __syncthreads();
    for (int l = 1; l < ib; ++l) {
        const float* Vl = Ps + (size_t)l * ldp;
        float pz[IB];
        #pragma unroll
        for (int t = 0; t < IB; ++t) pz[t] = 0.f;
        for (int rr = l + tid; rr < ldp; rr += TPB) {
            float vl = (rr == l) ? 1.f : Vl[rr];
            for (int i = 0; i < l; ++i) { const float* Vi = Ps + (size_t)i * ldp; float vi = (rr == i) ? 1.f : Vi[rr]; pz[i] += vi * vl; }
        }
        for (int i = 0; i < l; ++i) { float v = pz[i]; for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o); if (lane == 0) red[i * NWARP + warp] = v; }
        __syncthreads();
        if (tid < l) { float zz = 0.f; for (int wi = 0; wi < NWARP; ++wi) zz += red[tid * NWARP + wi]; zsh[tid] = zz; }
        __syncthreads();
        float tl = taus[l];
        for (int i = tid; i < l; i += TPB) {
            float acc = 0.f;
            for (int m = i; m < l; ++m) acc += Tg[(size_t)(co + i) + (size_t)(co + m) * NBMAX] * zsh[m];
            Tg[(size_t)(co + i) + (size_t)(co + l) * NBMAX] = -tl * acc;
        }
        __syncthreads();
    }
    // write factored inner sub-panel back to global Acm
    for (int idx = tid; idx < ldp * ib; idx += TPB) {
        int j = idx / ldp, rr = idx % ldp;
        Acm[(size_t)(ps + j) * n + (ps + rr)] = Ps[rr + j * ldp];
    }
    __syncthreads();
}

// Apply inner block's IB reflectors (just-factored, in global Acm cols
// [ps,ps+ib), rows>=ps, implicit unit diag) to wide-panel columns [c0,c1) in
// global Acm: C -= V (Tib^T (V^T C)). Tib is the IB-diagonal block of Tg.
// Uses smem buffers Wbuf (ib*wcols) and Vbuf (RB*ib).
template <int TPB, int IB, int NBMAX, int RB>
__device__ void wpanel_apply_inner(float* __restrict__ Acm, const float* __restrict__ Tg,
                                   float* Wbuf, float* Vbuf, float* Tib,
                                   int n, int p, int ps, int ib, int c0, int c1) {
    const int tid = threadIdx.x;
    int wcols = c1 - c0;
    if (wcols <= 0) return;
    int co = ps - p;
    // cache Tib (ib x ib upper-tri) contiguous Tib[l + i*ib]
    for (int idx = tid; idx < ib * ib; idx += TPB) Tib[idx] = Tg[(size_t)(co + idx % ib) + (size_t)(co + idx / ib) * NBMAX];
    __syncthreads();
    // W = V^T C  (ib x wcols)
    for (int idx = tid; idx < ib * wcols; idx += TPB) Wbuf[idx] = 0.f;
    __syncthreads();
    for (int r0 = ps; r0 < n; r0 += RB) {
        int rb = RB; if (r0 + rb > n) rb = n - r0;
        for (int idx = tid; idx < rb * ib; idx += TPB) {
            int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = ps + i;
            float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
            Vbuf[rr + i * RB] = vv;
        }
        __syncthreads();
        for (int idx = tid; idx < ib * wcols; idx += TPB) {
            int g = idx / ib, i = idx % ib;
            const float* Cg = Acm + (size_t)(c0 + g) * n;
            float acc = 0.f;
            for (int rr = 0; rr < rb; ++rr) acc += Vbuf[rr + i * RB] * Cg[r0 + rr];
            Wbuf[i + g * ib] += acc;
        }
        __syncthreads();
    }
    // W' = -Tib^T W (overwrite into Wbuf' region? reuse: store into same Wbuf after read)
    // need a second buffer; pack W' right after W in Wbuf is not possible in-place per-col.
    // We do it per (i,g) reading all l (W still intact), writing to a temp then copy.
    // Simpler: compute W'[i,g] into registers row-by-row is hard; use Vbuf-adjacent? Instead
    // we negate-and-transform in place column by column: for each g, Wp[i]=sum_{l<=i}Tib[l,i]W[l,g].
    // Since Wp[i] depends only on W[l<=i,g] (same column), we can compute top-down into a small
    // per-thread array when one thread owns a whole column. Assign columns to threads:
    for (int g = tid; g < wcols; g += TPB) {
        float wcol[IB];
        for (int i = 0; i < ib; ++i) wcol[i] = Wbuf[i + g * ib];
        float wp[IB];
        for (int i = 0; i < ib; ++i) { float acc = 0.f; for (int l = 0; l <= i; ++l) acc += Tib[l + i * ib] * wcol[l]; wp[i] = -acc; }
        for (int i = 0; i < ib; ++i) Wbuf[i + g * ib] = wp[i];
    }
    __syncthreads();
    // C += V W'
    for (int r0 = ps; r0 < n; r0 += RB) {
        int rb = RB; if (r0 + rb > n) rb = n - r0;
        for (int idx = tid; idx < rb * ib; idx += TPB) {
            int i = idx / rb, rr = idx % rb, r = r0 + rr, ci = ps + i;
            float vv = (r < ci) ? 0.f : (r == ci ? 1.f : Acm[(size_t)ci * n + r]);
            Vbuf[rr + i * RB] = vv;
        }
        __syncthreads();
        for (int idx = tid; idx < rb * wcols; idx += TPB) {
            int g = idx / rb, rr = idx % rb, r = r0 + rr;
            float* Cg = Acm + (size_t)(c0 + g) * n;
            float acc = 0.f;
            int imax = r - ps; if (imax >= ib) imax = ib - 1;
            for (int i = 0; i <= imax; ++i) acc += Vbuf[rr + i * RB] * Wbuf[i + g * ib];
            Cg[r] += acc;
        }
        __syncthreads();
    }
}

// Build the OFF-DIAGONAL blocks of the wide NB x NB compact-WY T, reading the
// full reflector panel V (cols [p,p+nb), rows>=p) from GLOBAL Acm. The diagonal
// IB-blocks were already filled by wpanel_inner_factor. For l-th column,
// z[i]=V[:,i]^T V[:,l] for i<l (only cross-block pairs are not yet set, but we
// recompute all i<l for simplicity over global), then T[:l,l] = -tau_l T[:l,:l] z.
template <int TPB, int NBMAX>
__device__ void wpanel_build_T(float* __restrict__ Acm, float* __restrict__ Tg,
                               const float* __restrict__ taus_wide,
                               float* red, float* zsh,
                               int n, int p, int nb, int IB) {
    const int NWARP = TPB / 32;
    const int tid = threadIdx.x;
    const int lane = tid & 31, warp = tid >> 5;
    // For each l, only fill rows i in EARLIER inner blocks (i < block_start(l)),
    // because the within-block upper-tri was set by the inner factor. Recomputing
    // all i<l would overwrite the correct within-block values with a recurrence
    // that is also correct, but to be safe we only touch the off-diagonal rows.
    for (int l = 1; l < nb; ++l) {
        int lb = (l / IB) * IB;       // start of l's inner block
        if (lb == 0) continue;        // l in first block -> all-within-block, already done
        const float* Vl = Acm + (size_t)(p + l) * n;
        // z[i] = V[:,i]^T V[:,l] for i in [0, lb)
        float pz[NBMAX];
        #pragma unroll
        for (int t = 0; t < NBMAX; ++t) pz[t] = 0.f;
        for (int r = p + l + tid; r < n; r += TPB) {
            float vl = Vl[r];                       // diag handled: r>p+l so V[r,l] real; r==p+l excluded
            for (int i = 0; i < lb; ++i) {
                const float* Vi = Acm + (size_t)(p + i) * n;
                float vi = (r == p + i) ? 1.f : Vi[r];
                pz[i] += vi * vl;
            }
        }
        // add the r==p+l term (V[p+l,l]=1) : contributes vi(p+l) * 1
        // handled separately to avoid divergence: thread owning r=p+l
        // (each i: vi at r=p+l is Vi[p+l] since p+l>p+i)
        for (int i = 0; i < lb; ++i) {
            float v = pz[i];
            for (int o = 16; o > 0; o >>= 1) v += __shfl_down_sync(0xffffffff, v, o);
            if (lane == 0) red[i * NWARP + warp] = v;
        }
        __syncthreads();
        if (tid < lb) { float zz = 0.f; for (int wi = 0; wi < NWARP; ++wi) zz += red[tid * NWARP + wi];
            // add r==p+l contribution: V[p+l, tid]*1
            zz += Acm[(size_t)(p + tid) * n + (p + l)];
            zsh[tid] = zz; }
        __syncthreads();
        float tl = taus_wide[l];
        // T[0:lb, l] = -tl * (T[0:lb,0:lb] applied)  but T[0:lb,0:l] includes cross terms.
        // Full dlarft: T[:l,l] = -tl * T[:l,:l] * z[:l]. We only update rows [0,lb).
        for (int i = tid; i < lb; i += TPB) {
            float acc = 0.f;
            for (int m = i; m < l; ++m) acc += Tg[(size_t)i + (size_t)m * NBMAX] * zsh_or_within(Tg, zsh, n, p, m, l, lb, NBMAX);
            Tg[(size_t)i + (size_t)l * NBMAX] = -tl * acc;
        }
        __syncthreads();
    }
}
"""

