        __syncthreads();
        if (tid == 0) { pj[rj] = 1.f; taus[j] = tval; }
        __syncthreads();
        int ntrail = ib - (j + 1);
        if (ntrail > 0) {
            float pw[IB];
            #pragma unroll
            for (int t = 0; t < IB; ++t) pw[t] = 0.f;
            for (int rr = rj + tid; rr < ldp; rr += TPB) {
                float vr = pj[rr];
                for (int t = 0; t < ntrail; ++t) pw[t] += vr * Ps[(size_t)(j + 1 + t) * ldp + rr];
            }
            for (int t = 0; t < ntrail; ++t) {
