template <int TPB, int NBMAX, int CT, int RB>
static size_t coop2_trail_smem(int ldv, int nb) {
    // Vfull(ldv*nb) + Ts(nb*nb) + Ws(nb*CT) + Wps(nb*CT) + Cs(RB*CT)
    return ((size_t)ldv * nb + (size_t)NBMAX * NBMAX + 2 * (size_t)NBMAX * CT
            + (size_t)RB * CT) * sizeof(float);
}

template <int TPB, int NBMAX, int CT, int RB>
static void coop2_run(float* Acm, float* Tg, float* tau, int B, int n) {
    int sms = 0; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, 0);
    // V-resident trailing: smem includes the full panel V (ldv*nb), largest at
    // p=0 (ldv=n). Allow that much dynamic smem; size the grid for its (lowest)
    // occupancy so the heaviest panel is covered (later panels reuse the grid).
    size_t trail_sh_max = coop2_trail_smem<TPB, NBMAX, CT, RB>(n, NBMAX);
    cudaFuncSetAttribute(qr_trailing_kernel<TPB, NBMAX, CT, RB>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize, (int)trail_sh_max);
    int tgrid = trailing_max_grid<TPB, NBMAX, CT, RB>(trail_sh_max);
    if (tgrid < 1) tgrid = sms;
    // panel kernel: dynamic smem ldp*nb (sized per p); cap to device opt-in.
    cudaFuncSetAttribute(qr_panel_kernel<TPB, NBMAX>,
                         cudaFuncAttributeMaxDynamicSharedMemorySize, (int)((size_t)n * NBMAX * sizeof(float)));
    for (int p = 0; p < n; p += NBMAX) {
        int nb = NBMAX; if (p + nb > n) nb = n - p;
        size_t panel_sh = (size_t)(n - p) * nb * sizeof(float);
        qr_panel_kernel<TPB, NBMAX><<<B, TPB, panel_sh>>>(Acm, Tg, tau, B, n, p, nb);
        if (p + nb < n) {
            size_t trail_sh = coop2_trail_smem<TPB, NBMAX, CT, RB>(n - p, nb);
            qr_trailing_kernel<TPB, NBMAX, CT, RB><<<tgrid, TPB, trail_sh>>>(Acm, Tg, B, n, p, nb);
        }
    }
}

